TRUNCATE dw.fact_customer_acquisition;
INSERT INTO dw.fact_customer_acquisition (customer_id, signup_date, first_order_date, region)
SELECT c.customer_id, c.signup_date, MIN(o.order_date), c.region
FROM staging.customers c
LEFT JOIN staging.orders o ON c.customer_id = o.customer_id
GROUP BY c.customer_id, c.signup_date, c.region;
